def sum_positive(nums):
    total = 0
    for n in nums:
        if n > 0:
            total += n
    return total

def check_order(order):
    problems = []
    if "qty" not in order:
        problems.append("missing qty")
    elif order["qty"] <= 0:
        problems.append("qty must be positive")
    if order.get("price", 0) < 0:
        problems.append("price must not be negative")
    return problems
